input.script:
export const meta = {
  name: 'scan-txt-files',
  description: 'Count .txt files in the working directory by Glob and Read, then report DONE',
  phases: [
    { title: 'Scan', detail: 'count files' },
    { title: 'Report', detail: 'confirm completion' },
  ],
}

phase('Scan')
const scan = await agent(
  "Use the Glob tool with pattern '*.txt'. Then use the Read tool on each file that matched. Finally reply with only the number of files found, as a plain integer.",
  { label: 'scan:files', phase: 'Scan' }
)

phase('Report')
const report = await agent(
  "Reply with exactly the single word: DONE",
  { label: 'report', phase: 'Report' }
)

return { scan, report }

